def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full-height separator column.
    sep = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    n = min(len(left[0]), len(right[0]))

    def mode(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    left_bg = mode(left)
    right_bg = mode(right)

    # Use the right panel's non-background color as the output background.
    right_counts = {}
    for row in right:
        for value in row:
            if value != right_bg:
                right_counts[value] = right_counts.get(value, 0) + 1
    out_bg = max(right_counts, key=right_counts.get) if right_counts else right_bg

    out = [[out_bg for _ in range(n)] for _ in range(h)]
    for r in range(h):
        for c in range(n):
            if left[r][c] != left_bg and right[r][c] != right_bg:
                out[r][c] = 3
    return out
