    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    bg1, bg2 = background(panels[0]), background(panels[1])
    rows, cols = len(panels[0]), len(panels[0][0])
    out = [[4 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if panels[0][r][c] != bg1 and panels[1][r][c] != bg2:
                out[r][c] = 3
