def transform(grid):
    h, w = len(grid), len(grid[0])

    # Count colors globally; the separator is a uniform line whose color
    # is much less common than the large background regions.
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1

    candidates = []
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append((freq[grid[0][c]], "v", c))
    for r in range(h):
        if all(value == grid[r][0] for value in grid[r]):
            candidates.append((freq[grid[r][0]], "h", r))

    _, direction, pos = min(candidates)

    if direction == "v":
        a = [row[:pos] for row in grid]
        b = [row[pos + 1:] for row in grid]
        width = min(len(a[0]), len(b[0]))
        shared = set(value for row in a for value in row) & set(
            value for row in b for value in row
        )
        fill = min(shared, key=lambda x: (-freq.get(x, 0), x)) if shared else 0
        return [
            [3 if a[r][c] == b[r][c] else fill for c in range(width)]
            for r in range(h)
        ]

    a, b = grid[:pos], grid[pos + 1:]
    height = min(len(a), len(b))
    shared = set(value for row in a for value in row) & set(
        value for row in b for value in row
    )
    fill = min(shared, key=lambda x: (-freq.get(x, 0), x)) if shared else 0
    return [
        [3 if a[r][c] == b[r][c] else fill for c in range(w)]
        for r in range(height)
    ]
